import React from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { FiUser, FiBook, FiClock } from 'react-icons/fi';

const CourseCard = ({ course }) => {
  const {
    id,
    title,
    description,
    category,
    level,
    teacherId,
    enrolledStudents,
    createdAt
  } = course;

  // Format the description to be shorter if needed
  const shortDescription = description.length > 100
    ? `${description.substring(0, 100)}...`
    : description;

  // Format date
  const formatDate = (dateString) => {
    const options = { year: 'numeric', month: 'long', day: 'numeric' };
    return new Date(dateString).toLocaleDateString('ar-EG', options);
  };

  return (
    <motion.div
      whileHover={{ y: -5 }}
      transition={{ duration: 0.3 }}
      className="card overflow-hidden"
    >
      <div className="relative pb-2/3 bg-gray-200">
        {/* Placeholder for course image - can be replaced with actual image later */}
        <div className="absolute inset-0 flex items-center justify-center bg-primary-100 dark:bg-primary-900">
          <FiBook className="h-16 w-16 text-primary-600 dark:text-primary-300" />
        </div>
      </div>
      
      <div className="p-4">
        <div className="flex justify-between items-start mb-2">
          <span className="inline-block px-2 py-1 text-xs font-semibold rounded-full bg-primary-100 text-primary-800 dark:bg-primary-900 dark:text-primary-200">
            {category}
          </span>
          <span className="inline-block px-2 py-1 text-xs font-semibold rounded-full bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-200">
            {level}
          </span>
        </div>
        
        <h3 className="text-xl font-bold mb-2 text-gray-900 dark:text-white">{title}</h3>
        
        <p className="text-gray-600 dark:text-gray-300 mb-4">{shortDescription}</p>
        
        <div className="flex justify-between items-center text-sm text-gray-500 dark:text-gray-400 mb-4">
          <div className="flex items-center">
            <FiUser className="mr-1" />
            <span>{enrolledStudents.length} طالب</span>
          </div>
          <div className="flex items-center">
            <FiClock className="mr-1" />
            <span>{formatDate(createdAt)}</span>
          </div>
        </div>
        
        <Link to={`/courses/${id}`} className="btn-primary block text-center">
          عرض الكورس
        </Link>
      </div>
    </motion.div>
  );
};

export default CourseCard;
